import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { validateCatalog, type CatalogEntry } from '../../src/registry';
import { REPO_ROOT } from '../helpers/v1-cli';

/**
 * Nothing from V1 is lost (docs/v2/07 §1 principle 1, §2 mapping). Bodies must equal the V1
 * source with its YAML frontmatter removed; frontmatter is regenerated by adapters.
 */
const V1 = join(REPO_ROOT, '.claude');
const AGENT_SKILLS = join(REPO_ROOT, '.agents', 'skills');

const report = validateCatalog(join(REPO_ROOT, 'catalog'));
const byId = new Map(report.loaded.map((item) => [item.entry.id, item]));

function stripFrontmatter(text: string): string {
  return text.replace(/^---\n[\s\S]*?\n---\n+/, '');
}

function v1Source(relativePath: string): string {
  return stripFrontmatter(readFileSync(join(REPO_ROOT, relativePath), 'utf8'));
}

function bodyOf(id: string): string {
  const item = byId.get(id);
  if (!item) throw new Error(`Missing catalog entry ${id}`);
  const body = (item.entry as CatalogEntry & { body?: string | null }).body;
  if (!body) throw new Error(`Entry ${id} has no body`);
  return readFileSync(resolve(dirname(item.file), body), 'utf8');
}

function resourceOf(id: string, endsWith: string): string {
  const item = byId.get(id);
  if (item?.entry.kind !== 'Skill') throw new Error(`${id} is not a skill`);
  const resource = item.entry.resources.find((path) => path.endsWith(endsWith));
  if (!resource) throw new Error(`${id} has no resource ending with ${endsWith}`);
  return readFileSync(resolve(dirname(item.file), resource), 'utf8');
}

const AGENT_ALIASES: Array<[file: string, id: string, aliasOf: string | null]> = [
  ['backend', 'agent.backend', 'agent.implementer'],
  ['code-reviewer', 'agent.code-reviewer', 'agent.reviewer'],
  ['copywriter-seo', 'agent.copywriter-seo', 'agent.writer'],
  ['frontend', 'agent.frontend', 'agent.implementer'],
  ['mobile', 'agent.mobile', 'agent.implementer'],
  ['project-manager', 'agent.project-manager', 'agent.analyst'],
  ['qa', 'agent.qa', 'agent.tester'],
  ['security-auditor', 'agent.security-auditor', null],
  ['systems-architect', 'agent.systems-architect', 'agent.architect'],
  ['test-engineer', 'agent.test-engineer', 'agent.tester'],
  ['ui-ux-designer', 'agent.ui-ux-designer', 'agent.designer'],
];

const RESOLVERS: Array<[file: string, id: string]> = [
  ['react-build-resolver', 'skill.build-resolve-react'],
  ['react-native-resolver', 'skill.build-resolve-react-native'],
  ['node-build-resolver', 'skill.build-resolve-node'],
  ['prisma-resolver', 'skill.build-resolve-prisma'],
];

const SKILLS: Array<[source: string, id: string]> = [
  ['.claude/skills/code-review/SKILL.md', 'skill.code-review'],
  ['.claude/skills/data-transform/SKILL.md', 'skill.data-transform'],
  ['.claude/skills/deploy/SKILL.md', 'skill.deploy'],
  ['.claude/skills/incremental-implementation/SKILL.md', 'skill.incremental-implementation'],
  ['.claude/skills/security-review/SKILL.md', 'skill.security-review'],
  ['.claude/skills/tdd/SKILL.md', 'skill.tdd'],
  ['.agents/skills/nestjs-backend/SKILL.md', 'skill.nestjs-backend'],
  ['.agents/skills/nodejs-backend/SKILL.md', 'skill.nodejs-backend'],
  ['.agents/skills/react-frontend/SKILL.md', 'skill.react-frontend'],
  ['.agents/skills/react-native-mobile/SKILL.md', 'skill.react-native-mobile'],
];

const v1Commands = readdirSync(join(V1, 'commands')).map((file) => file.replace(/\.md$/, ''));
const v1Rules = readdirSync(join(V1, 'rules'))
  .map((file) => file.replace(/\.md$/, ''))
  .filter((name) => name !== 'TIERS' && name !== 'react-native');
const v1References = readdirSync(join(V1, 'references'));
const v1McpServers = Object.keys(
  (JSON.parse(readFileSync(join(V1, 'mcp-configs', 'mcp-servers.json'), 'utf8')) as { mcpServers: object }).mcpServers,
);

describe('V1 → catalog migration (W2.0-05, docs/v2/07 §2)', () => {
  it.each(AGENT_ALIASES)('agent %s keeps its V1 body as %s', (file, id, aliasOf) => {
    const entry = byId.get(id)?.entry;

    expect(entry?.kind).toBe('Agent');
    expect(entry?.kind === 'Agent' ? entry.aliasOf : undefined).toBe(aliasOf);
    expect(bodyOf(id)).toBe(v1Source(`.claude/agents/${file}.md`));
  });

  it.each(RESOLVERS)('resolver agent %s becomes skill %s with the same body', (file, id) => {
    expect(bodyOf(id)).toBe(v1Source(`.claude/agents/${file}.md`));
  });

  it.each(SKILLS)('skill %s keeps its body as %s', (source, id) => {
    expect(bodyOf(id)).toBe(v1Source(source));
  });

  it.each(['code-review', 'tdd'])('keeps the divergent .agents variant of %s as a resource', (name) => {
    expect(resourceOf(`skill.${name}`, 'agent-skills-variant.md')).toBe(
      stripFrontmatter(readFileSync(join(AGENT_SKILLS, name, 'SKILL.md'), 'utf8')),
    );
  });

  it('keeps the long deploy workflow document as a resource', () => {
    expect(resourceOf('skill.deploy', 'deploy.md')).toBe(v1Source('.claude/skills/deploy/deploy.md'));
  });

  it.each(v1Commands)('command %s becomes a workflow with the same body', (name) => {
    expect(byId.get(`wf.${name}`)?.entry.kind).toBe('Workflow');
    expect(bodyOf(`wf.${name}`)).toBe(v1Source(`.claude/commands/${name}.md`));
  });

  it.each(v1Rules)('rule %s keeps its body', (name) => {
    expect(byId.get(`rule.${name}`)?.entry.kind).toBe('Rule');
    expect(bodyOf(`rule.${name}`)).toBe(v1Source(`.claude/rules/${name}.md`));
  });

  it('does not migrate the project-specific react-native rule into the default catalog (TD-08)', () => {
    expect(byId.has('rule.react-native')).toBe(false);
  });

  it.each(v1References)('reference %s is preserved', (file) => {
    const copy = join(REPO_ROOT, 'catalog', 'references', file);

    expect(existsSync(copy) && readFileSync(copy, 'utf8')).toBe(readFileSync(join(V1, 'references', file), 'utf8'));
  });

  it('turns the V1 tiers into three profiles', () => {
    expect(['profile.starter', 'profile.standard', 'profile.strict'].map((id) => byId.get(id)?.entry.kind)).toEqual([
      'Profile',
      'Profile',
      'Profile',
    ]);
  });

  it.each(v1McpServers)('MCP server %s becomes a tool entry', (name) => {
    expect(byId.get(`tool.mcp-${name}`)?.entry.kind).toBe('Tool');
  });

  it('keeps the CodeGraph integration as a tool', () => {
    expect(byId.get('tool.codegraph')?.entry.kind).toBe('Tool');
  });
});
